// === Tab: mySketch ===
let grassColor
let duckColor
let beakColor

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	grassColor = color('#44b863')
	duckColor = color('#fdffa3')
	beakColor = color('#fac975')
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	ortho(-width/2, width/2, -height/2, height/2, 0.1, 2000)
	background(grassColor)
	noStroke()

	orbitControl()

	rotateX(-PI/4)

	const r = 200
	const targetSize = 3*r
	scale(Math.max(width, height) / targetSize)

	const t = millis()

	// How much to offset each successive duck's walk cycle by,
	// in milliseconds. This is a big prime number so that it's
	// unlikely any two ducks will be at the same point in their
	// walk cycle.
	const tStagger = 5351

	// How long it takes the ducks to walk a whole circle, in ms
	const duckPeriod = 20 * 1000
	const duckSpeed = TWO_PI / duckPeriod

	const numDucks = 20
	rotateY(t * duckSpeed)
	for (let i = 0; i < numDucks; i++) {
		push()
		rotateY(i/numDucks * TWO_PI)
		translate(r, 0, 0)
		duck(t + i*tStagger)
		pop()
	}
}

function duck(t) {
	push()
	fill(duckColor)

	// body
	push()
	translate(
		sin(t*0.02/3)*5,
		sin(t*0.02)*3,
		0
	)
	sphere(10)

	// Legs
	push()
	fill(beakColor)
	for (const side of [-1, 1]) {
		push()
		scale(side, 1, 1)
		rotateX(PI*0.1)
		translate(3, 7, 0)
		rotateX(sin(t*0.02 + side*0.5*PI)*PI*0.2)
		const legHeight = 8
		translate(0, legHeight/2, 0)
		cylinder(1, legHeight)
		translate(0, legHeight/2, 0)
		rotateX(PI/2)
		scale(1.5)
		triangle(0, 3, -2, -5, 2, -5)
		pop()
	}
	pop()

	// tail
	rotateX(-PI*0.1)
	translate(0, 0, 4)
	sphere(9)
	translate(0, 0, 3)
	rotateX(PI*0.1)
	scale(1, 0.8, 1.5)
	sphere(9)
	pop()

	// head
	push()
	// Same as the body but with a bit of a time offset
	translate(
		sin(t*0.02/3 - 200)*5,
		-12 + sin(t*0.02 - 200)*3,
		-8
	)
	sphere(8)

	// eyes
	push()
	fill(0)
	translate(0, 0, -8)
	for (const side of [-1, 1]) {
		push()
		translate(side * 3, 0, 0)
		sphere(1)
		pop()
	}
	pop()

	// beak
	push()
	fill(beakColor)
	translate(0, 2, -6)
	scale(1.5, 0.4, 3)
	sphere(3)
	pop()

	pop()

	pop()
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
